import{_ as r,C as a,o as i,c as d,j as e,a as s,E as n,a2 as l}from"./chunks/framework.TaNiW7i8.js";const f=JSON.parse('{"title":"Synchronisation","description":"","frontmatter":{"title":"Synchronisation"},"headers":[],"relativePath":"guide/sync.md","filePath":"guide/sync.md"}'),u={name:"guide/sync.md"};function c(m,t,g,p,h,v){const o=a("Capture");return i(),d("div",null,[t[0]||(t[0]=e("h1",{id:"synchronisation",tabindex:"-1"},[s("Synchronisation "),e("a",{class:"header-anchor",href:"#synchronisation","aria-label":'Permalink to "Synchronisation"'},"​")],-1)),t[1]||(t[1]=e("p",null,"Votre mémoire est un dépôt git ordinaire. Kessho la synchronise avec le git installé sur votre ordinateur, vers le distant que vous choisissez, et ne force jamais rien. Un témoin vous dit aussi quand la mémoire vient de changer.",-1)),n(o,{name:"synchro",alt:"La synchronisation de la mémoire : fichiers modifiés depuis le dernier commit et message de commit en cours de saisie."}),t[2]||(t[2]=l('<h2 id="ce-que-vous-voyez" tabindex="-1">Ce que vous voyez <a class="header-anchor" href="#ce-que-vous-voyez" aria-label="Permalink to &quot;Ce que vous voyez&quot;">​</a></h2><p>La synchronisation se pilote à deux endroits : la barre d&#39;état, pour un clic, et <a href="/Kessho/guide/settings.html">Réglages</a> &gt; <strong>Synchronisation</strong>, pour le détail.</p><ul><li><strong>Dans la barre d&#39;état</strong>, en bas de la fenêtre : <ul><li>le bouton <strong>Synchroniser la mémoire</strong>, tout à gauche (infobulle : « Synchroniser : commiter, récupérer, pousser ») ;</li><li>le champ <strong>GIT</strong>, qui dit où en est le dépôt : <strong>à jour</strong>, <strong>N à pousser</strong>, <strong>N à récupérer</strong>, <strong>N non commités</strong>, <strong>conflit</strong> ou <strong>opération en cours</strong>. L&#39;infobulle donne la ligne d&#39;état complète.</li></ul></li><li><strong>Dans Réglages &gt; Synchronisation</strong> : <ul><li><strong>La ligne d&#39;état</strong> : la branche et son suivi, puis le retard et l&#39;avance, par exemple « main → origin/main · 2 à pousser · 0 à récupérer · distant consulté 10:30 ». L&#39;heure est celle de la dernière consultation du distant.</li><li><strong>Les trois gestes</strong> : <strong>Synchroniser</strong>, <strong>Récupérer</strong>, <strong>Pousser</strong>.</li><li><strong>Changements</strong> : le nombre de fichiers modifiés, supprimés et non suivis (« 3 modifiés · 0 supprimés · 1 non suivis »), la liste dépliable <strong>Voir la liste</strong>, le champ <strong>Message de commit</strong> et le bouton <strong>Commiter les changements</strong>.</li><li><strong>Distant</strong> : l&#39;adresse du dépôt distant, et le champ <strong>URL du distant (https ou ssh)</strong>.</li><li><strong>Automatisme</strong> : la case « Les agents commitent et synchronisent automatiquement ».</li><li><strong>Messages de commit</strong> : une ligne par origine (<strong>Un clic</strong>, <strong>Automatisme</strong>, <strong>Manuel</strong>, <strong>Agent IA</strong>) avec le modèle choisi et son <strong>Aperçu</strong>, puis <strong>Mes modèles</strong> et le bouton <strong>Nouveau modèle</strong>.</li><li><strong>Signalements</strong>, quand il y a quelque chose à dire.</li></ul></li><li><strong>Le témoin de fraîcheur</strong>, en haut à droite, à côté de votre avatar : une pastille qui s&#39;allume quand la mémoire change.</li></ul><p>Si la mémoire n&#39;est pas encore un dépôt, la section dit : « Cette mémoire n&#39;est pas un dépôt git. L&#39;initialiser ne crée aucun commit et ne la relie à aucun distant. » Si git n&#39;est pas installé, elle affiche « git introuvable » avec la commande pour l&#39;installer. Le reste de Kessho fonctionne sans git.</p><h2 id="ce-que-vous-pouvez-faire" tabindex="-1">Ce que vous pouvez faire <a class="header-anchor" href="#ce-que-vous-pouvez-faire" aria-label="Permalink to &quot;Ce que vous pouvez faire&quot;">​</a></h2><h3 id="synchroniser-en-un-clic" tabindex="-1">Synchroniser en un clic <a class="header-anchor" href="#synchroniser-en-un-clic" aria-label="Permalink to &quot;Synchroniser en un clic&quot;">​</a></h3><p>Cliquez <strong>Synchroniser la mémoire</strong> dans la barre d&#39;état. Kessho fait trois choses, dans cet ordre :</p><ol><li>il commite ce qui a changé, sous le message que compose le modèle de l&#39;origine <strong>Un clic</strong>, par défaut « vault backup: AAAA-MM-JJ HH:mm:ss » (rien n&#39;est commité s&#39;il n&#39;y a rien de nouveau) ;</li><li>il récupère les nouveautés du distant ;</li><li>il pousse vos commits.</li></ol><p>Rien n&#39;est mis de côté et rien n&#39;est forcé. À la fin, le champ <strong>GIT</strong> se met à jour ; un lecteur d&#39;écran entend « Mémoire synchronisée. ».</p><p>Si quelque chose bloque, la barre affiche « échec : » suivi d&#39;un mot (<strong>conflit</strong>, <strong>hors ligne</strong>, <strong>authentification</strong>, <strong>arbre sale</strong>, <strong>occupé</strong>, <strong>délai</strong>, <strong>identité</strong>, <strong>marqueurs</strong>). Passez la souris dessus pour lire la raison complète. Si le commit de sauvegarde a eu lieu avant l&#39;échec, le message le précise : il est fait localement.</p><p>Le bouton est grisé, avec la raison en infobulle, quand aucun distant n&#39;est connecté (« Aucun distant : connectez-en un plus bas. ») ou qu&#39;une opération git est déjà en cours.</p><h3 id="commiter-vos-changements-a-la-main" tabindex="-1">Commiter vos changements à la main <a class="header-anchor" href="#commiter-vos-changements-a-la-main" aria-label="Permalink to &quot;Commiter vos changements à la main&quot;">​</a></h3><p>Dans <strong>Changements</strong> :</p><ol><li>Cliquez <strong>Voir la liste</strong> pour lire les fichiers concernés.</li><li>Écrivez un <strong>Message de commit</strong>.</li><li>Cliquez <strong>Commiter les changements</strong>, puis <strong>Confirmer</strong> à la question « Commiter N changements avec ce message ? ». <strong>Annuler</strong> abandonne.</li></ol><p>Le champ est pré-rempli par le modèle de l&#39;origine <strong>Manuel</strong> (par défaut « vault backup: AAAA-MM-JJ HH:mm:ss ») : vous pouvez le modifier ; dès que vous écrivez dedans, Kessho ne le remplace plus. Le bouton reste grisé tant que le message est vide. Le message ne peut pas dépasser 1 000 caractères. Il faut que votre nom et votre courriel de commit soient renseignés dans votre profil (le rond avec votre initiale, en haut à droite).</p><h3 id="recuperer-ou-pousser" tabindex="-1">Récupérer ou pousser <a class="header-anchor" href="#recuperer-ou-pousser" aria-label="Permalink to &quot;Récupérer ou pousser&quot;">​</a></h3><ul><li><strong>Récupérer</strong> va chercher les nouveautés du distant et les applique. Il est grisé tant que des changements ne sont pas commités : « Des changements non commités empêchent la récupération : commitez-les d&#39;abord. »</li><li><strong>Pousser</strong> envoie vos commits. Il est grisé quand il n&#39;y a rien à pousser.</li><li><strong>Synchroniser</strong> récupère, puis pousse.</li></ul><p>Kessho ne récupère jamais tout seul : la ligne d&#39;état affiche « N à récupérer », et c&#39;est à vous de décider.</p><h3 id="connecter-un-distant" tabindex="-1">Connecter un distant <a class="header-anchor" href="#connecter-un-distant" aria-label="Permalink to &quot;Connecter un distant&quot;">​</a></h3><p>Dans <strong>Distant</strong>, collez l&#39;adresse du dépôt dans <strong>URL du distant (https ou ssh)</strong> et cliquez <strong>Connecter</strong> (le bouton devient <strong>Modifier</strong> quand un distant est déjà connecté). Les formes acceptées sont <code>https://hôte/chemin</code>, <code>ssh://hôte/chemin</code> et <code>utilisateur@hôte:chemin</code>.</p><p>Aucun identifiant n&#39;est stocké : Kessho utilise ceux de votre système. Une adresse qui en contient un est refusée.</p><h3 id="initialiser-le-depot" tabindex="-1">Initialiser le dépôt <a class="header-anchor" href="#initialiser-le-depot" aria-label="Permalink to &quot;Initialiser le dépôt&quot;">​</a></h3><p>Si votre mémoire n&#39;est pas encore un dépôt, cliquez <strong>Initialiser le dépôt</strong>. Cela ne crée aucun commit et ne la relie à aucun distant.</p><h3 id="laisser-vos-agents-synchroniser" tabindex="-1">Laisser vos agents synchroniser <a class="header-anchor" href="#laisser-vos-agents-synchroniser" aria-label="Permalink to &quot;Laisser vos agents synchroniser&quot;">​</a></h3><p>La case <strong>Automatisme</strong> (« Les agents commitent et synchronisent automatiquement ») est cochée par défaut. Quand elle l&#39;est, chaque outil de vos agents IA qui écrit dans la mémoire commite ce qu&#39;il a touché, et lui seul, puis pousse. Vos changements non commités ne partent jamais avec lui. Décochez la case pour reprendre la main.</p><p>La première ligne du message de ces commits se règle dans <a href="#composer-le-message-de-vos-commits">Composer le message de vos commits</a>.</p><p>Pour demander une synchronisation à un agent, voir <a href="/Kessho/agent/synchroniser.html">Synchroniser la mémoire</a>. Les outils correspondants sont décrits dans la <a href="/Kessho/reference/mcp/git.html">référence MCP</a>.</p><h3 id="composer-le-message-de-vos-commits" tabindex="-1">Composer le message de vos commits <a class="header-anchor" href="#composer-le-message-de-vos-commits" aria-label="Permalink to &quot;Composer le message de vos commits&quot;">​</a></h3><p>Dans <strong>Messages de commit</strong> (Réglages &gt; Synchronisation, visible quand la mémoire est un dépôt git), chaque origine de commit compose son message d&#39;après un <strong>modèle</strong> : l&#39;un des modèles livrés, ou le vôtre. Le modèle règle la première ligne du message. Tant que vous n&#39;y touchez pas, rien ne change : chaque origine garde son message habituel.</p><h4 id="les-quatre-origines" tabindex="-1">Les quatre origines <a class="header-anchor" href="#les-quatre-origines" aria-label="Permalink to &quot;Les quatre origines&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Origine</th><th>Ce que le modèle règle</th><th>Modèle par défaut</th></tr></thead><tbody><tr><td><strong>Un clic</strong></td><td>Le message du commit fait par le bouton <strong>Synchroniser la mémoire</strong>.</td><td><strong>Horodaté</strong> : <code>vault backup: {date} {heure_s}</code>, soit « vault backup: 2026-10-21 14:05:09 ».</td></tr><tr><td><strong>Automatisme</strong></td><td><strong>Seulement la première ligne</strong> du commit qu&#39;un outil de vos agents IA fait après avoir écrit. Le corps, qui liste les fichiers, et les lignes <code>Kessho-Outil</code>, <code>Kessho-Embarque</code> et <code>Kessho-Repris</code> restent toujours.</td><td><strong>Kessho · outil</strong> : <code>kessho({outil}): {objet} {demande}</code>, par exemple « kessho(mem_note): Architecture ».</td></tr><tr><td><strong>Manuel</strong></td><td>Le contenu pré-rempli du champ <strong>Message de commit</strong> ; vous pouvez le modifier avant de commiter.</td><td><strong>Horodaté</strong></td></tr><tr><td><strong>Agent IA</strong></td><td>Le message d&#39;un commit demandé à l&#39;agent par <code>mem_git_commit</code>. Le message de l&#39;agent est toujours conservé : le modèle de l&#39;agent ne peut que l&#39;entourer (il doit contenir <code>{message}</code>, sinon il est ignoré avec un avertissement), et un message vide est toujours refusé.</td><td><strong>Message de l&#39;agent</strong> : <code>{message}</code>, le message tel que l&#39;agent l&#39;a écrit.</td></tr></tbody></table><p>Le message de la résolution d&#39;un conflit n&#39;est jamais concerné : Kessho le compose lui-même.</p><p>Le sujet composé par un modèle est coupé à 72 caractères (avec « … ») pour tous les modèles, sauf <strong>Kessho · outil</strong> et <strong>Message de l&#39;agent</strong>, qui ne sont jamais coupés ; l&#39;origine <strong>Agent IA</strong> n&#39;y est jamais soumise. Quand un sujet est coupé, Kessho le signale.</p><p>Si le modèle choisi ne se rend plus, Kessho utilise le modèle par défaut de l&#39;origine et le dit : l&#39;<strong>Aperçu</strong> affiche « Le modèle enregistré est introuvable ou invalide : le modèle par défaut est utilisé. » Pour l&#39;origine <strong>Un clic</strong>, le commit part avec le modèle par défaut et la barre d&#39;état affiche un avertissement non bloquant, « modèle par défaut utilisé ». La synchronisation ne s&#39;arrête avant tout commit que si aucun message exploitable n&#39;a pu être composé ; l&#39;échec s&#39;affiche alors dans la barre d&#39;état.</p><h4 id="choisir-un-modele" tabindex="-1">Choisir un modèle <a class="header-anchor" href="#choisir-un-modele" aria-label="Permalink to &quot;Choisir un modèle&quot;">​</a></h4><ol><li>Sur la ligne de l&#39;origine, cliquez le nom du modèle : un menu s&#39;ouvre, avec <strong>Modèles livrés</strong> et <strong>Mes modèles</strong>.</li><li>Choisissez-en un : il est enregistré aussitôt, et l&#39;<strong>Aperçu</strong> de la ligne se met à jour.</li><li>Pour revenir au modèle par défaut de l&#39;origine, cliquez <strong>Rétablir le défaut</strong> (le bouton n&#39;apparaît que si vous avez changé).</li></ol><h4 id="les-six-modeles-livres" tabindex="-1">Les six modèles livrés <a class="header-anchor" href="#les-six-modeles-livres" aria-label="Permalink to &quot;Les six modèles livrés&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Nom</th><th>Modèle</th><th>Exemple</th></tr></thead><tbody><tr><td><strong>Horodaté</strong></td><td><code>vault backup: {date} {heure_s}</code></td><td>vault backup: 2026-10-21 14:05:09</td></tr><tr><td><strong>Journal</strong></td><td><code>{date} {heure} · {utilisateur|—}</code></td><td>2026-10-21 14:05 · Ben</td></tr><tr><td><strong>Conventional Commits</strong></td><td><code>chore(vault): {action|mise à jour} {n_total|plusieurs} note(s)</code></td><td>chore(vault): modification 4 note(s)</td></tr><tr><td><strong>Trace d&#39;agent</strong></td><td><code>[{origine}] {outil} — {objet}</code></td><td>[automatisme] mem_note — Architecture</td></tr><tr><td><strong>Kessho · outil</strong></td><td><code>kessho({outil}): {objet} {demande}</code></td><td>kessho(mem_note): Architecture (apply)</td></tr><tr><td><strong>Message de l&#39;agent</strong></td><td><code>{message}</code></td><td>correction de la note</td></tr></tbody></table><p>Aucun modèle livré n&#39;emploie de variable sensible (voir la mise en garde plus bas).</p><h4 id="la-syntaxe-d-un-modele" tabindex="-1">La syntaxe d&#39;un modèle <a class="header-anchor" href="#la-syntaxe-d-un-modele" aria-label="Permalink to &quot;La syntaxe d&#39;un modèle&quot;">​</a></h4><ul><li><code>{variable}</code> est remplacée par sa valeur au moment du commit.</li><li><code>{variable|défaut}</code> donne un texte de repli quand la variable est vide. Le texte de repli ne peut pas contenir d&#39;accolade.</li><li><code>{{</code> écrit une accolade ouvrante, <code>}}</code> une accolade fermante.</li><li>Un modèle tient sur <strong>une seule ligne</strong> et compte 500 caractères au plus ; le message obtenu ne peut pas dépasser 1 000 caractères ni être vide.</li><li>Une variable inconnue, une accolade sans sa paire ou un caractère de contrôle sont refusés avec un message qui dit quoi, et où quand il s&#39;agit d&#39;une position : une faute de frappe ne part jamais dans l&#39;historique. L&#39;éditeur liste alors les variables valides.</li><li>Une variable sans valeur donne son repli, sinon rien : un commit n&#39;échoue pas pour un compteur absent.</li></ul><h4 id="les-variables" tabindex="-1">Les variables <a class="header-anchor" href="#les-variables" aria-label="Permalink to &quot;Les variables&quot;">​</a></h4><p>Elles sont rangées par famille dans l&#39;éditeur, où un clic sur une variable l&#39;insère à l&#39;emplacement du curseur. Quand une variable n&#39;a pas de valeur pour l&#39;origine que vous prévisualisez, l&#39;éditeur le dit : elle restera vide, sauf valeur de repli.</p><table tabindex="0"><thead><tr><th>Famille</th><th>Variable</th><th>Ce qu&#39;elle donne</th><th>Exemple</th></tr></thead><tbody><tr><td>Temps</td><td><code>{date}</code></td><td>Date du jour</td><td>2026-10-21</td></tr><tr><td>Temps</td><td><code>{heure}</code></td><td>Heure, sans les secondes</td><td>14:05</td></tr><tr><td>Temps</td><td><code>{heure_s}</code></td><td>Heure, avec les secondes</td><td>14:05:09</td></tr><tr><td>Temps</td><td><code>{iso}</code></td><td>Date et heure complètes (ISO 8601), avec le fuseau</td><td>2026-10-21T14:05:09+02:00</td></tr><tr><td>Temps</td><td><code>{semaine}</code></td><td>Numéro de la semaine</td><td>43</td></tr><tr><td>Temps</td><td><code>{fuseau}</code></td><td>Décalage horaire local</td><td>+02:00</td></tr><tr><td>Volume</td><td><code>{n_modifies}</code></td><td>Nombre de notes modifiées (pas pour l&#39;automatisme)</td><td>3</td></tr><tr><td>Volume</td><td><code>{n_ajoutes}</code></td><td>Nombre de notes ajoutées (pas pour l&#39;automatisme)</td><td>1</td></tr><tr><td>Volume</td><td><code>{n_supprimes}</code></td><td>Nombre de notes supprimées (pas pour l&#39;automatisme)</td><td>0</td></tr><tr><td>Volume</td><td><code>{n_total}</code></td><td>Nombre total de notes touchées (pas pour l&#39;automatisme)</td><td>4</td></tr><tr><td>Contexte</td><td><code>{utilisateur}</code></td><td>Votre nom, tel que signé dans le Profil</td><td>Ben</td></tr><tr><td>Contexte</td><td><code>{appareil}</code> (sensible)</td><td>Nom de cet ordinateur</td><td>MacBook-de-Ben</td></tr><tr><td>Contexte</td><td><code>{memoire}</code></td><td>Nom de la mémoire (son dossier)</td><td>SecondBrain</td></tr><tr><td>Contexte</td><td><code>{branche}</code></td><td>Branche git courante</td><td>main</td></tr><tr><td>Contexte</td><td><code>{version}</code></td><td>Version de Kessho</td><td>0.3.1</td></tr><tr><td>Origine</td><td><code>{origine}</code></td><td>Origine du commit</td><td>un-clic</td></tr><tr><td>Origine</td><td><code>{outil}</code></td><td>Outil qui a écrit (automatisme seulement)</td><td>mem_note</td></tr><tr><td>Origine</td><td><code>{objet}</code></td><td>Objet de l&#39;écriture, par exemple le titre d&#39;une note (automatisme seulement)</td><td>Architecture</td></tr><tr><td>Origine</td><td><code>{message}</code></td><td>Message saisi (n&#39;a de vraie valeur que pour l&#39;agent ; l&#39;aperçu manuel montre un exemple)</td><td>correction de la note</td></tr><tr><td>Origine</td><td><code>{demande}</code></td><td>Mode de la demande de l&#39;outil (automatisme seulement)</td><td>(apply)</td></tr><tr><td>Action</td><td><code>{action}</code></td><td>Nature du changement : ajout, modification, suppression (pas pour l&#39;automatisme ; vide quand il n&#39;y a aucun changement)</td><td>modification</td></tr><tr><td>Contenu</td><td><code>{zones}</code> (sensible)</td><td>Zones de la mémoire touchées</td><td>10-episodes, 20-knowledge</td></tr><tr><td>Contenu</td><td><code>{projets}</code> (sensible)</td><td>Projets touchés</td><td>kessho, atelier</td></tr><tr><td>Contenu</td><td><code>{fichiers}</code> (sensible)</td><td>Notes touchées (les premières, puis le reste en +N)</td><td>a.md, b.md +3</td></tr></tbody></table><p><code>{origine}</code> vaut <code>un-clic</code>, <code>automatisme</code>, <code>manuel</code> ou <code>agent</code>.</p><h4 id="mise-en-garde-ce-que-les-variables-sensibles-ecrivent" tabindex="-1">Mise en garde : ce que les variables sensibles écrivent <a class="header-anchor" href="#mise-en-garde-ce-que-les-variables-sensibles-ecrivent" aria-label="Permalink to &quot;Mise en garde : ce que les variables sensibles écrivent&quot;">​</a></h4><p>Les variables de contenu (<code>{zones}</code>, <code>{projets}</code>, <code>{fichiers}</code>) et <code>{appareil}</code> révèlent ce que contient votre mémoire ou le nom de votre ordinateur. Le message composé est écrit dans l&#39;historique git, puis poussé sur le dépôt distant que vous avez choisi : y figurer, c&#39;est y rester. Aucun modèle livré n&#39;en contient, et Kessho n&#39;en met jamais dans un modèle que vous n&#39;avez pas écrit. Dans l&#39;éditeur, elles sont repliées sous <strong>Variables sensibles</strong>, et dès que votre modèle en emploie une, une note de vie privée la nomme.</p><h4 id="creer-modifier-supprimer-un-modele-personnel" tabindex="-1">Créer, modifier, supprimer un modèle personnel <a class="header-anchor" href="#creer-modifier-supprimer-un-modele-personnel" aria-label="Permalink to &quot;Créer, modifier, supprimer un modèle personnel&quot;">​</a></h4><ul><li><strong>Nouveau modèle</strong> (ou <strong>Nouveau modèle…</strong> dans le menu d&#39;une origine) ouvre l&#39;éditeur. Donnez un <strong>Nom du modèle</strong> (1 à 40 caractères) et écrivez le <strong>Modèle</strong>. Vous pouvez en garder 20 au plus.</li><li>L&#39;<strong>Aperçu</strong> se met à jour en direct, avec le même moteur que le commit. Choisissez l&#39;origine prévisualisée sous <strong>Aperçu pour l&#39;origine</strong> : l&#39;aperçu se rend comme le commit de cette origine.</li><li>Tant que le modèle est refusé, <strong>Enregistrer le modèle</strong> reste grisé et le message d&#39;erreur dit pourquoi. Un modèle créé depuis la ligne d&#39;une origine est aussitôt choisi pour elle.</li><li><strong>Modifier</strong> rouvre un modèle de <strong>Mes modèles</strong>. Si vous quittez l&#39;éditeur avec des changements, Kessho demande « Abandonner les modifications de ce modèle ? ».</li><li><strong>Supprimer le modèle</strong> demande confirmation et nomme les origines qui l&#39;utilisent : elles reviennent à leur modèle par défaut.</li></ul><h3 id="comprendre-un-refus" tabindex="-1">Comprendre un refus <a class="header-anchor" href="#comprendre-un-refus" aria-label="Permalink to &quot;Comprendre un refus&quot;">​</a></h3><p>Les messages disent quoi faire. Les plus courants :</p><ul><li><strong>Conflit</strong> : la récupération est annulée et rien n&#39;a changé. Les fichiers en cause sont nommés : fusionnez-les à la main, commitez, puis synchronisez.</li><li><strong>Poussée refusée</strong> : le distant a avancé. Récupérez d&#39;abord. Rien n&#39;est jamais forcé.</li><li><strong>Hors ligne</strong> : le distant est injoignable. Rien n&#39;a changé, réessayez plus tard.</li><li><strong>Authentification refusée</strong> : Kessho emploie les identifiants de votre système. Pour GitHub en https, lancez « gh auth login » ; sinon passez le distant en SSH.</li><li><strong>Opération en cours</strong> ou <strong>dépôt occupé</strong> : un autre processus git travaille sur la mémoire. Attendez un instant.</li></ul><p>Dans <strong>Signalements</strong>, Kessho prévient aussi quand des marqueurs de conflit ont été commités dans un fichier, quand il a repris une opération interrompue, ou quand le greffon Obsidian Git synchronise la même mémoire (à deux, les automates se gênent : mettez ses intervalles à 0). Kessho ne modifie jamais la configuration d&#39;Obsidian.</p><h3 id="savoir-quand-la-memoire-a-change" tabindex="-1">Savoir quand la mémoire a changé <a class="header-anchor" href="#savoir-quand-la-memoire-a-change" aria-label="Permalink to &quot;Savoir quand la mémoire a changé&quot;">​</a></h3><p>Le témoin de fraîcheur, en haut à droite, s&#39;allume quand la mémoire change, par exemple quand un agent vient d&#39;écrire. Cliquez-le pour ouvrir son panneau.</p>',55)),n(o,{name:"fraicheur",alt:"Le témoin de fraîcheur, en haut à droite : un agent vient d'écrire dans la zone Procédures, le témoin s'allume et dit ce qui a bougé."}),t[3]||(t[3]=e("ul",null,[e("li",null,"La première ligne dit depuis quand : « Vu il y a une seconde. » Sans changement depuis l'ouverture : « Aucun changement depuis l'ouverture. » Si le relevé échoue : « Impossible de relever l'état de la mémoire. »"),e("li",null,[e("strong",null,"Mouvements depuis le dernier rechargement"),s(" liste les zones qui ont bougé, avec le nombre de mouvements : « Procédures 1 ». Ce nombre compte les mouvements, pas la taille de la zone : ajouter une note puis la retirer en fait deux.")]),e("li",null,"Quand une note a changé sans qu'aucune zone ne change de taille, le panneau le dit : « Une note a été modifiée, sans qu'aucune zone ne change de taille. »"),e("li",null,[e("strong",null,"Relire"),s(" recharge ce que l'écran affiche et remet le compteur à zéro.")])],-1))])}const q=r(u,[["render",c]]);export{f as __pageData,q as default};
